<template>
  <loading-element v-if="authStore.isLoading" />
  <div class="main bg-primary" v-else>
    <div class="rowSpaceBetween fullWidth mb-5">
      <TopDeck
        v-if="authStore.userInfos"
        firstElement="Catalogue"
        secondElement="de recettes"
        :coloredSecond="true"
        actionHeaderIcon="mdi-arrow-left"
        :actionheaderFunction="() => $router.push('/my_recipes')"
        actionHeaderColor="accent"
        actionHeaderTextColor="white"
      />
      <div class="rowCustom">
        <ThemeToggle />
        <AccountToggle />
      </div>
    </div>

    <div v-if="isAdmin">
      <v-btn color="accent" rounded="lg" @click="router.push('/base_recipes_import')" class="white-text-button mb-3 mr-3">
        <v-icon class="mr-1">mdi-plus</v-icon>
        <span>Importer des recettes de base</span>
      </v-btn>
      <v-btn color="accent" rounded="lg" @click="router.push('/base_recipes')" class="white-text-button mb-3">
        <v-icon class="mr-1">mdi-plus</v-icon>
        <span>Ajouter une recette de base</span>
      </v-btn>
    </div>

    <v-row no-gutters>
      <v-col cols="12" md="12" class="pr-2">
        <div class="pa-4 bg-secondary rounded-xl">
          <h1 class="text mb-4">Recettes mises en avant</h1>

          <!-- Recherche -->
          <v-text-field
            v-model="searchQuery"
            placeholder="Rechercher (titre, catégorie, notes)"
            hide-details
            density="compact"
            variant="tonal"
            prepend-inner-icon="mdi-magnify"
            class="searchField rounded-lg bg-tertiary mb-4"
            rounded="lg"
          />

          <!-- Filtres catégorie (chips) -->
          <div class="filter-section mb-3">
            <span class="filter-label">Catégorie</span>
            <div class="chips-row">
              <v-chip
                v-for="cat in mealCategories"
                :key="cat.value"
                :color="selectedCategory === cat.value ? 'accent' : ''"
                :variant="selectedCategory === cat.value ? 'flat' : 'tonal'"
                class="filter-chip"
                @click="selectedCategory = cat.value"
              >
                {{ cat.label }}
              </v-chip>
            </div>
          </div>

          <!-- Filtres calories (chips) -->
          <div class="filter-section mb-5">
            <span class="filter-label">Calories</span>
            <div class="chips-row">
              <v-chip
                v-for="range in calorieRanges"
                :key="range.label"
                :color="selectedCalorie === range.label ? 'accent' : ''"
                :variant="selectedCalorie === range.label ? 'flat' : 'tonal'"
                class="filter-chip"
                @click="selectedCalorie = range.label"
              >
                {{ range.label }}
              </v-chip>
            </div>
          </div>

          <!-- Loader -->
          <div v-if="isLoadingRecipes" class="d-flex justify-center my-10">
            <v-progress-circular indeterminate color="primary" />
          </div>

          <!-- Vide -->
          <v-alert v-else-if="!filteredRecipes.length" type="info" variant="tonal" class="mt-4">
            Aucune recette à afficher.
          </v-alert>

          <div v-for="(recipesByCat, catName) in groupedRecipes" :key="catName" class="mb-8">
            <div class="d-flex align-center justify-space-between mb-2 cursor-pointer" @click="toggleGroup(catName)">
              <h2 class="recipeContainerTitle mb-0">{{ $t(catName) }}</h2>
              <v-btn icon variant="text" color="grey-darken-1" size="small">
                <v-icon>{{ openGroups[catName] ? "mdi-chevron-up" : "mdi-chevron-down" }}</v-icon>
              </v-btn>
            </div>

            <v-expand-transition>
              <div v-show="openGroups[catName]" class="mt-2">
                <v-row dense>
                  <v-col v-for="item in recipesByCat" :key="item.id" cols="12" sm="6" md="4" lg="3">
                    <div style="position:relative">
                      <BaseRecipeCard
                        :item="item"
                        :disabled="addingIds.includes(item.id)"
                        :isAdmin="isAdmin"
                        @add="addToMyRecipes"
                        @view="openDetails"
                        @duplicate="duplicateRecipe"
                      />
                      <v-btn
                        v-if="isAdmin"
                        icon
                        size="x-small"
                        color="error"
                        variant="elevated"
                        style="position:absolute; top:8px; right:8px; z-index:2;"
                        @click.stop="confirmDelete(item)"
                      >
                        <v-icon>mdi-delete</v-icon>
                      </v-btn>
                    </div>
                  </v-col>
                </v-row>
              </div>
            </v-expand-transition>
          </div>
        </div>
      </v-col>
    </v-row>

    <v-dialog v-model="deleteDialog.open" max-width="400">
      <v-card>
        <v-card-title class="text-h6">Supprimer la recette ?</v-card-title>
        <v-card-text>« {{ deleteDialog.item?.title }} » sera définitivement supprimée.</v-card-text>
        <v-card-actions>
          <v-spacer />
          <v-btn variant="text" @click="deleteDialog.open = false">Annuler</v-btn>
          <v-btn color="error" :loading="deleteDialog.loading" @click="deleteRecipe">Supprimer</v-btn>
        </v-card-actions>
      </v-card>
    </v-dialog>

    <v-snackbar v-model="snack.show" :timeout="2500">{{ snack.text }}</v-snackbar>
    <v-snackbar v-if="errorMessage" color="error" timeout="3000" top right>{{ errorMessage }}</v-snackbar>
  </div>
</template>

<script>
import { ref, computed, onMounted, watch } from "vue";
import { useRouter } from "vue-router";
import LoadingElement from "@/components/Animations/LoadingElement.vue";
import TopDeck from "@/components/Utils/TopDeck.vue";
import { useAuthStore } from "@/store/auth_store";
import ThemeToggle from "@/components/Utils/ThemeToggle.vue";
import AccountToggle from "@/components/Utils/AccountToggle.vue";
import { addBaseRecipeToUser, getBaseRecipes, deleteBaseRecipe } from "@/service/base_recipe_service";
import BaseRecipeCard from '@/components/Kitchen/Recipes/BaseRecipeCard.vue';

export default {
  name: "BaseRecipesCatalog",
  components: { LoadingElement, TopDeck, ThemeToggle, AccountToggle, BaseRecipeCard },
  setup() {
    const authStore = useAuthStore();
    const errorMessage = ref("");
    const snack = ref({ show: false, text: "" });
    const router = useRouter();

    const recipes = ref([]);
    const isLoadingRecipes = ref(false);
    const searchQuery = ref("");
    const selectedCategory = ref("toutes");
    const selectedCalorie = ref("Toutes");
    const openGroups = ref({});
    const addingIds = ref([]);
    const isAdmin = computed(() => authStore.userInfos?.role === 'admin');

    // Catégories fixes
    const mealCategories = [
      { label: "Toutes", value: "toutes" },
      { label: "Petit déjeuner", value: "breakfast" },
      { label: "Déjeuner", value: "lunch" },
      { label: "Plat", value: "dinner" },
      { label: "Collation", value: "snack" },
    ];

    // Tranches de calories
    const calorieRanges = [
      { label: "Toutes", min: 0, max: Infinity },
      { label: "0 – 100 kcal", min: 0, max: 100 },
      { label: "100 – 200 kcal", min: 100, max: 200 },
      { label: "200 – 300 kcal", min: 200, max: 300 },
      { label: "300 – 400 kcal", min: 300, max: 400 },
      { label: "400 – 500 kcal", min: 400, max: 500 },
      { label: "500 – 600 kcal", min: 500, max: 600 },
      { label: "600 – 700 kcal", min: 600, max: 700 },
      { label: "+ 700 kcal", min: 700, max: Infinity },
    ];

    const selectedCalorieRange = computed(() =>
      calorieRanges.find(r => r.label === selectedCalorie.value) || calorieRanges[0]
    );

    const filteredRecipes = computed(() => {
      const q = searchQuery.value.trim().toLowerCase();
      const cat = selectedCategory.value;
      const { min, max } = selectedCalorieRange.value;

      return recipes.value.filter((item) => {
        const title = (item.title || "").toLowerCase();
        const category = String(item.category || "").toLowerCase();
        const notes = (item.notes || "").toLowerCase();
        const kcal = item.totals?.kcal ?? 0;

        const matchSearch = !q || title.includes(q) || category.includes(q) || notes.includes(q);
        const matchCategory = cat === "toutes" || item.category === cat;
        const matchCalorie = kcal >= min && kcal < max;

        return matchSearch && matchCategory && matchCalorie;
      });
    });

    const groupedRecipes = computed(() => {
      if (selectedCategory.value !== "toutes") {
        return { [selectedCategory.value]: filteredRecipes.value };
      }
      const groups = {};
      filteredRecipes.value.forEach((item) => {
        const cat = item.category || "Sans catégorie";
        if (!groups[cat]) groups[cat] = [];
        groups[cat].push(item);
      });
      return groups;
    });

    function toggleGroup(catName) {
      openGroups.value[catName] = !openGroups.value[catName];
    }

    function openDetails(id) {
      router.push({ name: 'recipe_detail', params: { id }, query: { source: 'base' } });
    }

    async function addToMyRecipes(item) {
      if (!authStore?.userid) { errorMessage.value = "Utilisateur non connecté."; return; }
      const key = item.id || item.baseId || item.title;
      if (addingIds.value.includes(key)) return;
      addingIds.value.push(key);
      try {
        const res = await addBaseRecipeToUser(authStore.userid, item, item.id);
        if (res && res.existed) {
          snack.value = { show: true, text: "Vous possédez déjà cette recette." };
        } else {
          snack.value = { show: true, text: "Recette ajoutée à vos recettes ✅" };
        }
      } catch (e) {
        console.error("Erreur ajout recette utilisateur:", e);
        errorMessage.value = "Erreur lors de l'ajout de la recette.";
      } finally {
        const idx = addingIds.value.indexOf(key);
        if (idx !== -1) addingIds.value.splice(idx, 1);
      }
    }

    onMounted(() => {
      watch(
        () => authStore.userInfos,
        async () => {
          if (!authStore?.userid) return;
          try {
            isLoadingRecipes.value = true;
            const data = await getBaseRecipes();
            recipes.value = Object.entries(data).map(([id, value]) => ({ id, ...value }));
            const cats = [...new Set(recipes.value.map((r) => r.category || "Sans catégorie"))];
            cats.forEach((cat) => { openGroups.value[cat] = true; });
          } catch (error) {
            console.error("Erreur récupération recettes:", error);
            errorMessage.value = "Erreur lors du chargement des recettes.";
          } finally {
            isLoadingRecipes.value = false;
          }
        },
        { immediate: true }
      );
    });

    const deleteDialog = ref({ open: false, item: null, loading: false });

    async function duplicateRecipe(item) {
      if (!item || !item.id) return;
      try {
        const { addBaseRecipe } = await import('@/service/base_recipe_service');
        const copy = { ...item };
        delete copy.id;
        copy.title = (copy.title || 'Recette') + ' (copie)';
        const { id } = await addBaseRecipe(copy);
        recipes.value = [...recipes.value, { ...copy, id }];
        snack.value = { show: true, text: 'Recette dupliquée ✅' };
      } catch(e) {
        console.error(e);
        snack.value = { show: true, text: 'Erreur lors de la duplication' };
      }
    }

    function confirmDelete(item) {
      deleteDialog.value = { open: true, item, loading: false };
    }

    async function deleteRecipe() {
      if (!deleteDialog.value.item) return;
      deleteDialog.value.loading = true;
      try {
        await deleteBaseRecipe(deleteDialog.value.item.id);
        recipes.value = recipes.value.filter(r => r.id !== deleteDialog.value.item.id);
        snack.value = { show: true, text: "Recette supprimée ✅" };
        deleteDialog.value.open = false;
      } catch (err) {
        console.error("Erreur suppression:", err);
        snack.value = { show: true, text: "Erreur lors de la suppression" };
      } finally {
        deleteDialog.value.loading = false;
      }
    }

    return {
      authStore, errorMessage, snack, router,
      recipes, searchQuery, selectedCategory, selectedCalorie,
      mealCategories, calorieRanges,
      addingIds, openGroups, toggleGroup,
      filteredRecipes, groupedRecipes,
      isLoadingRecipes, isAdmin,
      openDetails, addToMyRecipes,
      deleteDialog, confirmDelete, deleteRecipe, duplicateRecipe,
    };
  },
};
</script>

