<!-- src/components/Kitchen/Recipes/RecipeDetail.vue -->
<template>
    <div class="py-6 px-4 bg-primary main">
        <div class="rowSpaceBetween fullWidth mb-6">
          <TopDeck
            firstElement="Détail"
            secondElement="recette"
            :coloredSecond="true"
            actionHeaderIcon="mdi-arrow-left"
            :actionheaderFunction="() => $router.back()"
            actionHeaderColor="accent"
            actionHeaderTextColor="white"
          />
          <div class="rowCustom">
            <ThemeToggle />
            <AccountToggle />
          </div>
        </div>
        <v-card class="recipe-detail-card pa-6 rounded-xl" elevation="2" color="secondary">
          <!-- Header -->
          <div class="recipe-header mb-4">
            <div class="recipe-header__left">
              <div class="recipe-thumb" v-if="previewSrc">
                <v-img
                  class="recipe-thumb__img"
                  :src="previewSrc"
                  cover
                  @error="onPreviewError"
                  width="200"
                  height="200"
                >
                  <template #placeholder>
                    <v-row class="fill-height ma-0" align="center" justify="center">
                      <v-progress-circular indeterminate size="24"></v-progress-circular>
                    </v-row>
                  </template>
                </v-img>
              </div>
              <div class="recipe-header__info">
                <h1 class="text-h4 font-weight-bold recipe-title">
                  {{ recipe?.title || 'Sans titre' }}
                </h1>
                <div class="recipe-header__actions">
                  <v-chip
                    v-if="recipe?.category"
                    class="recipe-category-chip"
                    variant="tonal"
                    size="default"
                    prepend-icon="mdi-tag"
                  >
                    {{ $t(recipe.category) }}
                  </v-chip>
                  <v-btn
                    class="recipe-generate-btn"
                    variant="tonal"
                    @click="createShoppingListFromRecipe()"
                    prepend-icon="mdi-cart-plus"
                  >
                    Liste de courses
                  </v-btn>
                  <v-btn
                    v-if="canEditBaseRecipe"
                    class="recipe-action-btn"
                    icon
                    size="small"
                    variant="tonal"
                    @click="editRecipe()"
                  >
                    <v-icon size="18">mdi-pencil</v-icon>
                  </v-btn>
                  <v-btn
                    v-if="!recipe?.baseRecipe && !isFromBaseCatalog"
                    class="recipe-action-btn"
                    :color="recipe?.favorite ? 'warning' : ''"
                    icon
                    size="small"
                    variant="tonal"
                    @click="toggleFavorite()"
                  >
                    <v-icon size="18">{{ recipe?.favorite ? 'mdi-star' : 'mdi-star-outline' }}</v-icon>
                  </v-btn>
                  <v-btn
                    v-if="canEditBaseRecipe"
                    class="recipe-action-btn"
                    color="error"
                    icon
                    size="small"
                    variant="tonal"
                    @click="requestDelete"
                  >
                    <v-icon size="18">mdi-delete</v-icon>
                  </v-btn>
                </div>
              </div>
            </div>
          </div>

          <!-- Recette (notes) -->
          <div v-if="recipe?.notes" class="recipe-notes-wrapper mb-5">
            <div class="d-flex align-center mb-2">
              <v-icon size="small" class="mr-2 detail-icon">mdi-book-open-variant</v-icon>
              <span class="text-subtitle-2 font-weight-medium detail-text">Recette</span>
            </div>
            <div class="recipe-notes text-body-2 ml-7 detail-text" v-html="recipe.notes"></div>
          </div>

          <!-- Nova warning -->
          <v-alert
            v-if="novaWarning"
            :type="novaWarning.type"
            variant="tonal"
            class="mb-5"
            :icon="novaWarning.icon"
            prominent
            border="start"
          >
            {{ novaWarning.message }}
          </v-alert>

          <div class="recipe-split">
            <!-- Nutrition -->
            <div class="recipe-split__col recipe-split__col--nutrition">
              <div class="d-flex align-center mb-4">
                <v-icon class="mr-2 detail-icon">mdi-nutrition</v-icon>
                <h2 class="text-h6 font-weight-bold detail-text">Valeurs nutritionnelles</h2>
              </div>
              <v-card class="nutrition-card pa-4 rounded-lg" color="tertiary" elevation="0">
                <div class="text-body-1 mb-2 detail-text">
                  <v-icon size="small" class="mr-1 detail-icon">mdi-weight</v-icon>
                  <strong>{{ recipe?.totals?.grams ?? 0 }} g</strong> —
                  <v-icon size="small" class="mx-1 detail-icon">mdi-fire</v-icon>
                  <strong>{{ recipe?.totals?.kcal ?? 0 }} kcal</strong>
                </div>
                <v-divider class="my-2"></v-divider>
                <div class="text-body-2 detail-text">
                  <div class="d-flex justify-space-between mb-1">
                    <span>Protéines</span>
                    <strong>{{ format1(recipe?.totals?.protein) }} g</strong>
                  </div>
                  <div class="d-flex justify-space-between mb-1">
                    <span>Glucides</span>
                    <strong>{{ format1(recipe?.totals?.carbs) }} g</strong>
                  </div>
                  <div class="d-flex justify-space-between">
                    <span>Lipides</span>
                    <strong>{{ format1(recipe?.totals?.fat) }} g</strong>
                  </div>
                </div>
                <v-divider class="my-3" v-if="recipe?.servings && recipe.servings > 0"></v-divider>
                <div class="text-body-2 d-flex align-center detail-text" v-if="recipe?.servings && recipe.servings > 0">
                  <v-icon size="small" class="mr-2 detail-icon">mdi-account-multiple</v-icon>
                  <span><strong>Par portion ({{ recipe.servings }}) :</strong> {{ Math.round((recipe?.totals?.kcal ?? 0) / recipe.servings) }} kcal</span>
                </div>
              </v-card>
            </div>

            <!-- Ingrédients -->
            <div class="recipe-split__col recipe-split__col--ingredients">
              <div class="d-flex align-center mb-4">
                <v-icon class="mr-2 detail-icon">mdi-food-apple</v-icon>
                <h2 class="text-h6 font-weight-bold detail-text">Ingrédients</h2>
              </div>
              <v-alert v-if="!recipe?.ingredients?.length" type="info" variant="tonal" icon="mdi-information">
                Aucune ligne d'ingrédient.
              </v-alert>
              <v-list v-else density="compact" class="listTile ingredients-list rounded-lg">
                <template v-for="(ing, i) in recipe.ingredients" :key="i">
                  <v-list-item class="ingredient-item px-4 py-3">
                    <template v-slot:prepend>
                      <v-avatar size="40" class="mr-3 ingredient-avatar">
                        <v-icon size="22" class="ingredient-icon">mdi-food-variant</v-icon>
                      </v-avatar>
                    </template>
                    <div class="flex-grow-1">
                      <v-list-item-title class="font-weight-bold mb-2">
                        {{ ing.name || ing.productName }}
                      </v-list-item-title>
                      <div class="d-flex align-center gap-2">
                        <v-tooltip v-if="getNovaDisplay(ing.novaGroup)" :text="$t(getNovaDisplay(ing.novaGroup).string)">
                          <template v-slot:activator="{ props: tooltipProps }">
                            <v-chip
                              :color="getNovaDisplay(ing.novaGroup).color"
                              size="x-small"
                              variant="flat"
                              class="text-white font-weight-bold"
                              v-bind="tooltipProps"
                              label
                            >
                              Nova {{ getNovaNumber(ing.novaGroup) }}
                            </v-chip>
                          </template>
                        </v-tooltip>
                      </div>
                    </div>
                    <template v-slot:append>
                      <v-chip variant="tonal" size="small" label class="font-weight-bold">
                        <v-icon start size="16">mdi-weight-gram</v-icon>
                        {{ ing.grams }}g
                      </v-chip>
                    </template>
                  </v-list-item>
                  <v-divider v-if="i < recipe.ingredients.length - 1" class="my-0"></v-divider>
                </template>
              </v-list>
            </div>
          </div>
        </v-card>

        <v-dialog v-model="askDelete" max-width="420">
          <v-card>
            <v-card-title>Supprimer la recette ?</v-card-title>
            <v-card-text>Cette action est définitive.</v-card-text>
            <v-card-actions>
              <v-spacer/>
              <v-btn variant="text" @click="askDelete=false">Annuler</v-btn>
              <v-btn color="error" @click="deleteRecipe">Supprimer</v-btn>
            </v-card-actions>
          </v-card>
        </v-dialog>

        <v-snackbar v-model="snack.show" :timeout="2500">{{ snack.text }}</v-snackbar>
        <v-alert v-if="errorMessage" type="error" variant="tonal" class="mt-4">{{ errorMessage }}</v-alert>
    </div>
</template>

<script setup>
  import { ref, computed, onMounted, watch } from 'vue'
  import { useRouter, useRoute } from 'vue-router'
  import { useAuthStore } from '@/store/auth_store'
  import { getUserRecipeById, deleteRecipeFromUserCollection, setRecipeAsFavorite } from '@/service/recipe_service'
  import { getBaseRecipeById, deleteBaseRecipe } from '@/service/base_recipe_service'
  import { getIngredientsByBarcodes, getNovaStringAndColor } from '@/service/ingredient_service'
  import { addShoppingList, getUserShoppingLists } from '@/service/shopping_list_service'
  import TopDeck from '@/components/Utils/TopDeck.vue'
  import ThemeToggle from '@/components/Utils/ThemeToggle.vue'
  import AccountToggle from '@/components/Utils/AccountToggle.vue'

  /* eslint-disable no-undef */
  const props = defineProps({ id: { type: String, required: true } })
  /* eslint-enable no-undef */

  const router = useRouter()
  const route = useRoute()
  const authStore = useAuthStore()
  const recipe = ref(null)
  const isLoading = ref(false)
  const errorMessage = ref('')
  const snack = ref({ show: false, text: '' })
  const askDelete = ref(false)

  const isAdmin = computed(() => authStore.userInfos?.role === 'admin')
  const isFromBaseCatalog = computed(() => route.query?.source === 'base')
  const canEditBaseRecipe = computed(() => {
    if (!recipe.value) return false
    if (isFromBaseCatalog.value) return isAdmin.value
    return !recipe.value.baseRecipe || isAdmin.value
  })

  const validPreview = ref(true)
  const placeholderImage = 'https://www.mimisrecipes.com/wp-content/uploads/2018/12/recipe-placeholder-featured.jpg'
  const sourceKey = computed(() => recipe.value?.url || recipe.value?.image || recipe.value?.imageUrl || '')
  const previewSrc = computed(() => validPreview.value && sourceKey.value ? sourceKey.value : placeholderImage)
  function onPreviewError() { validPreview.value = false }

  const novaWarning = computed(() => {
    if (!recipe.value?.ingredients?.length) return null
    const novaGroups = recipe.value.ingredients
      .map(ing => { const d = getNovaDisplay(ing.novaGroup); if (!d) return null; const m = d.string.match(/\d+/); return m ? parseInt(m[0]) : null })
      .filter(n => n !== null)
    if (!novaGroups.length) return null
    const nova4Count = novaGroups.filter(n => n === 4).length
    const nova3Count = novaGroups.filter(n => n === 3).length
    if (nova4Count) return { type: 'error', icon: 'mdi-alert-circle', message: `Cette recette contient ${nova4Count} ingrédient(s) ultra-transformé(s) (Nova 4). Consommation à limiter.` }
    if (nova3Count > 1) return { type: 'warning', icon: 'mdi-alert', message: `Cette recette contient ${nova3Count} ingrédients transformés (Nova 3). À consommer avec modération.` }
    return null
  })

  function getNovaDisplay(novaGroup) {
    if (!novaGroup) return null
    let num = null
    if (typeof novaGroup === 'number') num = novaGroup
    else if (typeof novaGroup === 'object') { if (novaGroup.string) { const m = novaGroup.string.match(/\d+/); num = m ? parseInt(m[0]) : null } else if (typeof novaGroup.value === 'number') num = novaGroup.value }
    else if (typeof novaGroup === 'string') { const m = novaGroup.match(/\d+/); num = m ? parseInt(m[0]) : null }
    if (!num || num < 1 || num > 4) return null
    return getNovaStringAndColor(num)
  }

  function getNovaNumber(novaGroup) {
    if (!novaGroup) return null
    let num = null
    if (typeof novaGroup === 'number') num = novaGroup
    else if (typeof novaGroup === 'object') { if (novaGroup.string) { const m = novaGroup.string.match(/\d+/); num = m ? parseInt(m[0]) : null } else if (typeof novaGroup.value === 'number') num = novaGroup.value }
    else if (typeof novaGroup === 'string') { const m = novaGroup.match(/\d+/); num = m ? parseInt(m[0]) : null }
    return num
  }

  function format1(n) { const v = Number(n ?? 0); return Number.isFinite(v) ? v.toFixed(1) : '0.0' }

  async function loadRecipe() {
    if (!authStore.userid) return
    try {
      isLoading.value = true
      let r = await getUserRecipeById(authStore.userid, props.id)
      if (!r || r.baseRecipe === true) {
        const base = await getBaseRecipeById(props.id)
        if (base) r = base
        else if (!r) { errorMessage.value = 'Recette introuvable.'; return }
      }
      const barcodes = r.ingredients?.map(i => i.id) || []
      const fullInfos = await getIngredientsByBarcodes(authStore.userid, barcodes)
      const hydratedIngredients = (r.ingredients || []).map(line => {
        const found = fullInfos.find(f => f.id === line.id)
        return { ...line, name: line.name || found?.productName || line.id, productName: found?.productName || line.name || line.id, productBrand: found?.productBrand || '', novaGroup: line.novaGroup ?? found?.novaGroup ?? null, nutritionPer100g: found?.nutritionPer100g || {} }
      })
      recipe.value = { id: props.id, ...r, ingredients: hydratedIngredients }
    } catch (e) { console.error(e); errorMessage.value = "Erreur lors du chargement de la recette." }
    finally { isLoading.value = false }
  }

  async function deleteRecipe() {
    if (!canEditBaseRecipe.value) { errorMessage.value = "Action réservée aux administrateurs."; return }
    if (!authStore.userid || !recipe.value?.id) return
    try {
      if (recipe.value?.baseRecipe) await deleteBaseRecipe(recipe.value.id)
      else await deleteRecipeFromUserCollection(authStore.userid, recipe.value.id)
      askDelete.value = false
      snack.value = { show: true, text: 'Recette supprimée 🗑️' }
      setTimeout(() => router.push('/my_recipes'), 350)
    } catch (e) { console.error(e); errorMessage.value = "Erreur lors de la suppression." }
  }

  async function toggleFavorite() {
    if (!authStore.userid || !recipe.value?.id) return
    try {
      const next = !recipe.value.favorite
      await setRecipeAsFavorite(authStore.userid, recipe.value.id, next)
      recipe.value.favorite = next
      snack.value = { show: true, text: next ? 'Ajoutée aux favoris ⭐' : 'Retirée des favoris' }
    } catch (e) { console.error(e); errorMessage.value = "Erreur lors de la mise à jour du favori." }
  }

  async function createShoppingListFromRecipe() {
    if (!authStore.userid) { errorMessage.value = "Utilisateur non connecté."; return }
    const ingredients = recipe.value?.ingredients || []
    if (!ingredients.length) { errorMessage.value = "Aucun ingrédient à ajouter."; return }
    const items = ingredients.map(ing => {
      const name = String(ing.name || ing.productName || '').trim()
      if (!name) return null
      const grams = Number(ing.grams)
      return { name, quantity: Number.isFinite(grams) && grams > 0 ? `${grams} g` : 1 }
    }).filter(Boolean)
    if (!items.length) { errorMessage.value = "Aucun ingrédient valide."; return }
    const listName = (recipe.value?.title || "Liste de courses").trim()
    try {
      const existingLists = await getUserShoppingLists(authStore.userid)
      const alreadyGenerated = Object.values(existingLists || {}).some(list => list && String(list.name || '').trim().toLowerCase() === listName.toLowerCase() && list.userGenerated === false)
      if (alreadyGenerated) { snack.value = { show: true, text: "Cette liste existe déjà." }; return }
      await addShoppingList(authStore.userid, { name: listName, items, userGenerated: false })
      snack.value = { show: true, text: "Liste de courses créée." }
    } catch (e) { console.error(e); errorMessage.value = "Erreur lors de la création de la liste." }
  }

  function editRecipe() {
    if (!canEditBaseRecipe.value) { errorMessage.value = "Action réservée aux administrateurs."; return }
    if (recipe.value?.baseRecipe) router.push({ path: '/base_recipes', query: { id: recipe.value.id } })
    else router.push({ path: '/add_recipe', query: { id: recipe.value.id } })
  }

  function requestDelete() {
    if (!canEditBaseRecipe.value) { errorMessage.value = "Action réservée aux administrateurs."; return }
    askDelete.value = true
  }

  onMounted(() => { watch(() => authStore.userid, () => loadRecipe(), { immediate: true }) })
  watch(sourceKey, v => { validPreview.value = !!v })
</script>

<style scoped>
  .listTile { border-radius: 12px; background: rgba(var(--v-theme-tertiary)); }
  .recipe-detail-card { border: 1px solid rgba(var(--v-theme-text), 0.08); box-shadow: none; }
  .nutrition-card { border: 1px solid rgba(var(--v-theme-text), 0.08); background: rgba(var(--v-theme-tertiary), 0.9); }
  .ingredients-list { border: 1px solid rgba(var(--v-theme-text), 0.08); background: rgba(var(--v-theme-tertiary), 0.85); }

  .recipe-split { display: flex; align-items: flex-start; gap: 20px; }
  .recipe-split__col--nutrition { flex: 0 0 40%; min-width: 280px; }
  .recipe-split__col--ingredients { flex: 1 1 60%; min-width: 320px; }

  .detail-text { color: rgb(var(--v-theme-text)); }
  .detail-icon { color: rgb(var(--v-theme-text)); opacity: 0.6; }

  .recipe-header { display: flex; align-items: flex-start; gap: 20px; flex-wrap: wrap; }
  .recipe-header__left { display: flex; gap: 20px; align-items: flex-start; flex: 1; flex-wrap: nowrap; }
  .recipe-header__info { display: flex; flex-direction: column; gap: 12px; flex: 1; min-width: 0; }
  .recipe-header__actions { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }

  .recipe-thumb__img { border-radius: 16px; object-fit: cover; }
  .recipe-title { margin: 0; }

  .recipe-action-btn { border-radius: 999px; box-shadow: none !important; }
  .recipe-generate-btn { border-radius: 8px; font-weight: 600; text-transform: none; box-shadow: none !important; }

  .recipe-category-chip { font-weight: 600; box-shadow: none; }

  .recipe-notes-wrapper { background: rgba(var(--v-theme-secondary), 0.5); border: 1px solid rgba(var(--v-theme-text), 0.08); padding: 12px 16px; border-radius: 12px; }
  .recipe-notes :deep(p) { margin: 0 0 0.5em 0; }
  .recipe-notes :deep(p:last-child) { margin-bottom: 0; }
  .recipe-notes :deep(ul), .recipe-notes :deep(ol) { padding-left: 1.5em; margin: 0.5em 0; }
  .recipe-notes :deep(li) { margin: 0.25em 0; }
  .recipe-notes :deep(strong) { font-weight: bold; }
  .recipe-notes :deep(em) { font-style: italic; }
  .recipe-notes :deep(u) { text-decoration: underline; }

  .ingredient-item { transition: all 0.2s ease; }
  .ingredient-item:hover { background: rgba(var(--v-theme-primary), 0.08); }
  .ingredient-avatar { background: rgba(var(--v-theme-text), 0.06); border: 1px solid rgba(var(--v-theme-text), 0.1); }
  .ingredient-icon { color: rgb(var(--v-theme-text)); opacity: 0.5; }

  .rowCustom { display: flex; flex-direction: row; justify-content: flex-end; align-items: center; }

  @media (max-width: 980px) {
    .recipe-split { flex-direction: column; }
    .recipe-split__col--nutrition, .recipe-split__col--ingredients { flex: 1 1 auto; min-width: 0; }
    .recipe-header__left { flex-wrap: wrap; }
  }
</style>
