<template>
  <v-card
    class="recipe-card bg-tertiary"
    max-width="380"
    elevation="0"
  >
    <div class="recipe-media">
      <v-img
        class="recipe-img"
        height="190px"
        :src="previewSrc"
        cover
        @error="onPreviewError"
        style="cursor:pointer"
        @click="viewRecipe"
      >
        <template #placeholder>
          <v-row
            class="fill-height ma-0"
            align="center"
            justify="center"
          >
            <v-progress-circular indeterminate color="white"></v-progress-circular>
          </v-row>
        </template>
      </v-img>
      <div class="recipe-media__overlay"></div>
      <v-chip
        size="small"
        class="recipe-chip"
        variant="elevated"
        color="surface"
      >
        {{ $t(item.category) }}
      </v-chip>
    </div>

    <div class="recipe-body">
      <div class="recipe-title-row">
        <h3 class="recipe-title line-clamp-1">
          {{ item.title || "Sans titre" }}
        </h3>
      </div>

      <div class="recipe-meta" v-if="item.totals?.kcal || item.servings">
        <span class="recipe-meta__pill" v-if="item.totals?.kcal">
          {{ Math.round(item.totals.kcal) }} kcal
        </span>
      </div>

      <div class="recipe-actions">
        <v-btn
          class="recipe-btn"
          :disabled="disabled"
          color="accent"
          variant="tonal"
          @click="addToCatalog"
          block
        >
          Ajouter à mes recettes
        </v-btn>
      </div>
    </div>

    <!-- CONTENU DÉPLIABLE -->
    <v-expand-transition>
      <div v-show="show">
        <v-divider class="recipe-divider"></v-divider>

        <v-card-text class="recipe-details text-body-2 mt-2">
          <div>
            <strong>Totaux :</strong>
            {{ item.totals?.grams ?? 0 }} g —
            {{ item.totals?.kcal ?? 0 }} kcal
            <br />
            P {{ formatValue(item.totals?.protein) }} g •
            G {{ formatValue(item.totals?.carbs) }} g •
            L {{ formatValue(item.totals?.fat) }} g
          </div>

          <div
            v-if="item.servings && item.servings > 0"
            class="text-caption mt-1"
          >
            <strong>Par portion ({{ item.servings }}) :</strong>
            {{ Math.round((item.totals?.kcal ?? 0) / item.servings) }} kcal
          </div>
        </v-card-text>
      </div>
    </v-expand-transition>
  </v-card>
</template>

<script setup>
import { ref, computed, watch } from "vue";
/* eslint-disable no-undef */
const props = defineProps({
  item: { type: Object, required: true },
  disabled: { type: Boolean, default: false },
  isAdmin: { type: Boolean, default: false }
});
const emit = defineEmits(["add", "view", "duplicate"]);
/* eslint-enable no-undef */

const show = ref(false);

const validPreview = ref(true);
const placeholderImage = 'https://www.mimisrecipes.com/wp-content/uploads/2018/12/recipe-placeholder-featured.jpg';

const sourceKey = computed(() => props.item?.url || props.item?.image || props.item?.imageUrl || '');
const previewSrc = computed(() => validPreview.value && sourceKey.value ? sourceKey.value : placeholderImage);

function onPreviewError() { validPreview.value = false; }
watch(sourceKey, (v) => { validPreview.value = !!v; });

function addToCatalog() { emit('add', props.item); }
function viewRecipe() { emit('view', props.item.id); }
function formatValue(value) { return value?.toFixed ? value.toFixed(1) : value ?? 0; }
</script>

